import { OllamaClient } from './ollama.js';
export class ModelManager{base;constructor(base){this.base=base}async status(){try{const c=new OllamaClient(this.base,'');const r=await c.tags();return{base:this.base,online:true,models:(r.models||[]).map(m=>({name:String(m.name),size:Number(m.size||0),modifiedAt:m.modified_at,digest:m.digest}))}}catch(e){return{base:this.base,online:false,models:[],error:e instanceof Error?e.message:String(e)}}}async pull(model,onProgress){try{const r=await fetch(`${this.base.replace(/\/$/,'')}/api/pull`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:model,stream:true})});if(!r.ok)return{ok:false,error:`Ollama ${r.status}`};const reader=r.body?.getReader();if(reader){const decoder=new TextDecoder();let buffer='';while(true){const{value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split(/\r?\n/);buffer=lines.pop()||'';for(const line of lines)if(line.trim())onProgress?.(line)}}return{ok:true,model}}catch(e){return{ok:false,error:e instanceof Error?e.message:String(e)}}}}
